const input = $('When Executed by Another Workflow').first().json;
const updates = input.updates ?? {};
const allowedFields = ['FirstName', 'LastName', 'Phone', 'PreferredLanguage'];
const output = [];

for (const field of allowedFields) {
  const value = updates[field];
  // Only route fields explicitly provided with a non-empty value.
  if (value !== undefined && value !== null && String(value).trim() !== '') {
    output.push({ json: { field, value } });
  }
}

if (output.length === 0) {
  return [{ json: { field: '__NO_VALID_FIELDS__', value: null } }];
}

return output;

